-- A cursor's query runs at its first read, with the snapshot taken when it
-- opened: a cursor opened in a BEFORE trigger reads the row being inserted,
-- later commands of the transaction stay invisible, and errors and volatile
-- effects come from the read that runs it.
CREATE TABLE t256 (a int);
INSERT INTO t256 VALUES (1), (2);
CREATE TABLE log256 (a int);
CREATE FUNCTION open256() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE c refcursor := 'opened256';
BEGIN
  OPEN c FOR SELECT a FROM t256 ORDER BY a;
  INSERT INTO log256 VALUES (NEW.a);
  RETURN NEW;
END $$;
CREATE TRIGGER b256 BEFORE INSERT ON t256 FOR EACH ROW EXECUTE FUNCTION open256();
BEGIN;
INSERT INTO t256 VALUES (3);
SELECT name, is_scrollable FROM pg_cursors;
FETCH ALL FROM opened256;
FETCH BACKWARD 2 FROM opened256;
COMMIT;
DROP TRIGGER b256 ON t256;
CREATE FUNCTION read256() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE c refcursor; r record;
BEGIN
  OPEN c FOR SELECT count(*) AS n FROM log256;
  INSERT INTO log256 VALUES (NEW.a);
  FETCH c INTO r;
  RAISE NOTICE 'logged before %', r.n;
  CLOSE c;
  RETURN NEW;
END $$;
CREATE TRIGGER r256 BEFORE INSERT ON t256 FOR EACH ROW EXECUTE FUNCTION read256();
INSERT INTO t256 VALUES (4);
DROP TRIGGER r256 ON t256;
BEGIN;
DECLARE c256 CURSOR FOR SELECT a FROM t256 ORDER BY a DESC;
UPDATE t256 SET a = a + 10;
INSERT INTO t256 VALUES (99);
FETCH ALL FROM c256;
ROLLBACK;
BEGIN;
DECLARE g256 CURSOR FOR SELECT count(*) FROM t256;
DELETE FROM t256;
FETCH g256;
ROLLBACK;
CREATE SEQUENCE q256;
BEGIN;
DECLARE n256 CURSOR FOR SELECT nextval('q256') FROM t256 ORDER BY 1;
SELECT last_value, is_called FROM q256;
FETCH n256;
SELECT last_value, is_called FROM q256;
ROLLBACK;
BEGIN;
DECLARE z256 CURSOR FOR SELECT 1 / (a - a) FROM t256 ORDER BY 1;
FETCH z256;
ROLLBACK;
BEGIN;
DECLARE h256 CURSOR WITH HOLD FOR SELECT a FROM t256 ORDER BY a;
INSERT INTO t256 VALUES (7);
COMMIT;
FETCH ALL FROM h256;
CLOSE h256;
-- An open cursor keeps the tables it reads in use until it closes.
BEGIN;
DECLARE k256 CURSOR FOR SELECT a FROM t256 ORDER BY a;
DROP TABLE t256;
ROLLBACK;
BEGIN;
DECLARE k256 CURSOR FOR SELECT a FROM t256 ORDER BY a;
FETCH ALL FROM k256;
ALTER TABLE t256 ADD COLUMN b int;
ROLLBACK;
BEGIN;
DECLARE k256 CURSOR FOR SELECT a FROM t256 ORDER BY a;
CLOSE k256;
ALTER TABLE t256 ADD COLUMN b int;
ROLLBACK;
